excels.excel:

EXPORT WITH SHEET="合并-行", HEADER=true,
    MAPPING={"a":"部门","b":"姓名","c":"一季度","d":"二季度","e":"三季度","f":"四季度"},
    MERGE:{ROWS 1 WITH MERGE_WITH_FIRST, ROWS 2 WITH MERGE_WITH_CONCAT}


EXPORT WITH SHEET="合并-列", HEADER=true,
    MAPPING={"a":"部门","b":"姓名","c":"一季度","d":"二季度","e":"三季度","f":"四季度"},
    MERGE:{COLS A..F WITH MERGE_WITH_FIRST}
